    return {'week': week}

def generate(rng):
    n = rng.randint(4, 7)
    prices = rng.sample([1.5, 1.8, 2.0, 2.2, 2.5, 2.75, 3.0, 3.25, 3.5, 4.0, 4.5], n)
    k = rng.randint(2, n)
    words = {2: 'second', 3: 'third', 4: 'fourth', 5: 'fifth', 6: 'sixth', 7: 'seventh'}
    return {'prices': prices, 'k': k, 'ordinal': words[k]}

def generate(rng):
    days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    i = rng.randint(1, 6)
    return {'week': [rng.randint(150, 700) for _ in range(7)], 'i': i, 'day': days[i], 'new': rng.randint(701, 950)}

